# Remind an OPEN or PENDING claim on the sheet's today. A claim in any other status, or one already
# reminded on the sheet's today, is a 409 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
# Checks the rules and writes the reminded date only when none refuses it.
apply:
  class: net.officefloor.hq.app.claim.RemindClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the reminder is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReminded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# Void a claim. A change its status does not allow is a 409 and writes nothing. While the sheet has
# void reasons, a void without one of them is a 400 and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
# The reason chosen, if any.
validate:
  class: net.officefloor.hq.app.claim.ValidateVoid
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.VoidClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: log
# The status it was saved at, with who, when and its due then.
log:
  class: net.officefloor.hq.app.claim.LogClaimStatus
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimStatus
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Reminds an OPEN or PENDING claim on the sheet's today, once per day: any other status, or a
 * second reminder the same day, is refused and writes nothing. While the sheet's escalation gap is
 * set, a reminder whose previous one was at least that many days before the sheet's today escalates
 * the claim, once per claim ever.
 */
public class RemindClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, ClaimRepository repository, SettingsRepository settings,
            Out<ClaimEscalation> escalation) throws InvalidClaimStatusException {
        LocalDate previous = claim.getRemindedOn();
        claim.remind(sheet.today());
        if (!repository.remind(claim)) throw new InvalidClaimStatusException("The claim was already reminded today");
        Integer gap = settings.find(sheet.id()).escalateAfter();
        boolean due = gap != null && previous != null && !previous.plusDays(gap).isAfter(sheet.today());
        escalation.set(new ClaimEscalation(due && repository.escalate(claim)));
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.voidreason.VoidReason;
import net.officefloor.hq.app.voidreason.VoidReasonRepository;
import net.officefloor.plugin.variable.Val;

/**
 * Voids the claim. Only a role the permission matrix allows may void. A SETTLED claim may be
 * voided only by a steward, and only within {@link #SETTLED_DAYS} days of its settlement (its
 * status log's SETTLED date) by the sheet's today; it keeps its number and its frozen figure,
 * which leaves every total. While the sheet has void reasons, a void needs one of them, kept on
 * the claim.
 */
public class VoidClaim {
    /** How many days after its settlement a SETTLED claim may still be voided. */
    static final long SETTLED_DAYS = 7;

    public void apply(@Val Sheet sheet, @Val Claim claim, @Val VoidRequest body, RoleRepository roles,
            SettingsRepository settings, ClaimLogRepository log, VoidReasonRepository reasons,
            HttpServletRequest request) throws InvalidClaimStatusException, InvalidClaimException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("void", role)) {
            throw new InvalidClaimStatusException("A " + role + " may not void a claim");
        }
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            if (!Role.STEWARD.equals(role)) {
                throw new InvalidClaimStatusException("Only a steward may void a SETTLED claim: " + user + " is a " + role);
            }
            LocalDate settled = log.settledOn(claim);
            long days = settled == null ? -1 : ChronoUnit.DAYS.between(settled, sheet.today());
            if (days < 0 || days > SETTLED_DAYS) {
                throw new InvalidClaimStatusException("A SETTLED claim may be voided only within " + SETTLED_DAYS
                        + " days of its settlement" + (settled == null ? "" : " on " + settled));
            }
        }
        java.util.List<String> listed = reasons.findAll(sheet.id()).stream().map(VoidReason::reason).toList();
